"s.97233ce1":{"t":"Addicted to something, or otherwise passionate about gambling, squandering a great deal of money.","h":"0ce1760d"},
"s.44878e16":{"t":"Spends money on matters of the opposite sex; easily exploited financially.","h":"afc21b6a"},
"s.c1f1eb07":{"t":"Suffers major theft, robbery, or is ruined by fraud.","h":"442a88b9"},
"s.5a12304a":{"t":"Enjoys property left by predecessors.","h":"72cfca9f"},
"s.2f2ead90":{"t":"Good at trade, trusted by many people.","h":"11ae6156"},
"s.ac9515df":{"t":"Often meets disputes over money; earns money only after being involved in lawsuits.","h":"1dadfd79"},
