"s.97e6c33d":{"t":"Utter poverty and misery.","h":"0a6aa253"},
"s.c553bb5d":{"t":"Earning money is difficult at first, but easy later, and one becomes ever more comfortable in old age.","h":"a6fe0c83"},
"s.bb350187":{"t":"The Sun and Moon are both bright and either oppose or combine in a clash: great wealth.","h":"7d693ceb"},
"s.0cb151e1":{"t":"Relieves a good deal of illness and misfortune.","h":"634683c4"},
