"s.f7114cb6":{"t":"Little illness.","h":"ecd75c58"},
"s.4b70996f":{"t":"Little illness, but if many calamity-causing stars are met, illness lingers and recovery is slow.","h":"56b1e2ef"},
"s.cdc50295":{"t":"Recovers from illness and hardship quickly and unexpectedly.","h":"3e55c231"},
"s.5afed8eb":{"t":"Healthy for life, with little to worry about regarding illness or misfortune.","h":"15323a67"},
"s.ef55478e":{"t":"Poor eyesight, often imprisoned.","h":"b04af11c"},
"s.f5454da6":{"t":"Dies a miserable death.","h":"99ce1f15"},
"s.f17bd995":{"t":"Very poor eyesight; suffers traffic accidents or wounds from blades.","h":"7fafa4a8"},
"s.4c239e9f":{"t":"Dies suddenly and unexpectedly, either through an accident or through poisoning.","h":"078122e9"},
"s.3a34b098":{"t":"Yellow complexion; has a disorder of qi and blood or a skin disease.","h":"03f38bd0"},
"s.1aa73f57":{"t":"Has a defect or ailment of the head.","h":"28830eb7"},
"s.8d6b1ab7":{"t":"Suffers an accident with fairly serious injury to the head or face.","h":"4a83325f"},
